package dev.raf.radar;
import android.app.*;import android.content.*;import android.net.*;import android.os.*;import org.json.*;import java.util.*;
/** Opt-in local diagnostics; notifications never carry credentials or remote data. */
final class DiagnosticMode {
 static final String KEY="diagnosticMode";static final Map<String,Long> notified=new HashMap<>();
 static ConnectivityManager.NetworkCallback callback;
 static boolean enabled(){return Diagnostics.app!=null&&Diagnostics.app.getSharedPreferences("radar",0).getBoolean(KEY,false);}
 static void set(Context c,boolean enabled){c.getSharedPreferences("radar",0).edit().putBoolean(KEY,enabled).apply();Diagnostics.info("diagnostics",enabled?"mode_enabled":"mode_disabled");if(enabled){Diagnostics.worker.execute(()->{sample();Diagnostics.check();});}else{NotificationManager nm=c.getSystemService(NotificationManager.class);if(nm!=null)for(android.service.notification.StatusBarNotification n:nm.getActiveNotifications())if("diagnostics".equals(n.getTag()))nm.cancel("diagnostics",n.getId());}}
 static void init(){try{ConnectivityManager cm=Diagnostics.app.getSystemService(ConnectivityManager.class);callback=new ConnectivityManager.NetworkCallback(){public void onAvailable(Network n){Diagnostics.detail("network","available");}public void onLost(Network n){Diagnostics.once("network","connection_lost",true);}public void onCapabilitiesChanged(Network n,NetworkCapabilities c){Diagnostics.detail("network","capabilities",network());}};cm.registerDefaultNetworkCallback(callback);}catch(Exception e){Diagnostics.error("network","callback_failed",e,0,-1,-1,null);}}
 static JSONObject network(){JSONObject s=new JSONObject();try{Context app=Diagnostics.app;ConnectivityManager cm=app.getSystemService(ConnectivityManager.class);NetworkCapabilities c=cm.getNetworkCapabilities(cm.getActiveNetwork());String transport=c==null?"none":c.hasTransport(NetworkCapabilities.TRANSPORT_VPN)?"vpn":c.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?"wifi":c.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)?"cellular":c.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)?"ethernet":"other";s.put("transport",transport).put("validated",c!=null&&c.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)).put("vpn",c!=null&&c.hasTransport(NetworkCapabilities.TRANSPORT_VPN)).put("metered",cm.isActiveNetworkMetered()).put("roaming",c!=null&&!c.hasCapability(NetworkCapabilities.NET_CAPABILITY_NOT_ROAMING));}catch(Exception ignored){}return s;}
 static void sample(){if(!enabled())return;Diagnostics.detail("network","state",network());try{Runtime r=Runtime.getRuntime();PowerManager pm=Diagnostics.app.getSystemService(PowerManager.class);Debug.MemoryInfo m=new Debug.MemoryInfo();Debug.getMemoryInfo(m);Diagnostics.detail("resources","state","usedHeapKb",(r.totalMemory()-r.freeMemory())/1024,"maxHeapKb",r.maxMemory()/1024,"pssKb",m.getTotalPss(),"cpuMs",android.os.Process.getElapsedCpuTime(),"foreground",Diagnostics.foreground,"powerSave",pm.isPowerSaveMode(),"interactive",pm.isInteractive());Store store=new Store(Diagnostics.app);long now=System.currentTimeMillis();for(Point p:store.points())if(p.enabled){long since=store.prefs.getLong("diagMonitorSince",now),success=store.prefs.getLong("diagPointSuccess:"+p.id,0);Diagnostics.detail(Diagnostics.pointArea(p.id),"freshness","ageMs",Math.max(0,now-(success>0?success:since)));}Diagnostics.detail("load","minute",Diagnostics.load.snapshot(SystemClock.elapsedRealtime()));}catch(Exception e){Diagnostics.error("diagnostics","sample_failed",e,0,-1,-1,null);}}
 static void alert(String area,String event,String level,int http){if(!enabled()||("info".equals(level)&&!event.equals("session_recovery_succeeded"))||event.equals("manual_report"))return;try{Context app=Diagnostics.app;if(!Access.notifications(app))return;long now=SystemClock.elapsedRealtime();String category=area.startsWith("point_")?area:area.startsWith("yandex")?"yandex":area;String key=category+":"+event;Long before=notified.get(key);if(before!=null&&now-before<30000)return;if(notified.size()>256)notified.clear();notified.put(key,now);
  String label=area;if(area.startsWith("point_"))for(Point p:new Store(app).points())if(Diagnostics.pointArea(p.id).equals(area)){label=p.name;break;}
  String message=message(area,event,http);NotificationManager nm=app.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("diagnostics","Режим диагностики",NotificationManager.IMPORTANCE_HIGH));
  Intent intent=new Intent(app,MainActivity.class).putExtra("openDiagnostics",true);Notification n=new Notification.Builder(app,"diagnostics").setSmallIcon(R.drawable.ic_radar).setContentTitle("Диагностика · "+(area.startsWith("point_")?label:"Sense PRO")).setContentText(message).setStyle(new Notification.BigTextStyle().bigText(message)).setGroup("sense_diagnostics").setOnlyAlertOnce(true).setAutoCancel(true).setContentIntent(PendingIntent.getActivity(app,6100,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).build();nm.notify("diagnostics",Math.floorMod(category.hashCode(),100000)+6100,n);
 }catch(Exception ignored){}}
 static String message(String area,String event,int http){if(http==401)return "Запрос Яндекса не авторизован (401). Результат восстановления — в журнале.";if(http==403)return "Яндекс отказал в доступе (403). Откройте проверку входа.";if(http==429)return "Сервис ограничил частоту запросов (429). Очередь на паузе.";if(event.equals("session_recovery_succeeded"))return "Сессия восстановлена, запрос выполнен.";if(event.equals("session_recovery_failed"))return "Не удалось восстановить сессию Яндекса.";if(area.startsWith("point_"))return event.equals("retry_scheduled")?"Точка не обновилась. Повтор запланирован; подробности в журнале.":"Данные точки устарели. Проверьте журнал диагностики.";if(area.equals("gps"))return "Нет свежей геопозиции или отклонён GPS-замер: "+event;if(area.equals("monitor"))return "Очередь мониторинга: "+event;if(area.equals("account")||area.equals("statistics"))return "Не удалось связаться с сервером Sense PRO: "+event;if(area.equals("yandex_browser")||area.equals("taxi"))return "Сбой получения цены: "+event+(http>0?" (HTTP "+http+")":"");return "Событие: "+area+" / "+event;}
}
